import React, { useEffect, useState } from 'react';
import { PieChart, Pie, Cell, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import SlideBarComponent from '../../components/SlideBar/SlideBarComponent';
import './IncomeDepartment.scss';
import { getTotalIncomeByDepartment } from '../../api/static'; // ✅ đường dẫn đúng với file bạn tạo

const COLORS = ['#007bff', '#28a745', '#ffc107', '#dc3545', '#17a2b8', '#6f42c1', '#fd7e14'];

const IncomeDepartment = () => {
    const [data, setData] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchData = async () => {
            try {
                const res = await getTotalIncomeByDepartment();
                const transformed = res.summary.map(item => ({
                    name: item.department,
                    value: item.total_income
                }));
                setData(transformed);
            } catch (error) {
                console.error("Lỗi khi lấy dữ liệu thống kê:", error);
            } finally {
                setLoading(false);
            }
        };

        fetchData();
    }, []);

    return (
        <div className='container d-flex'>
            <div className='sidebar'>
                <SlideBarComponent />
            </div>

            <div className='content w-100'>
                <h3 className="mb-4">Thống Kê Theo Phòng Ban</h3>

                {loading ? (
                    <p>Đang tải dữ liệu...</p>
                ) : (
                    <div className="row">
                        <div className="col-md-6">
                            <table className="table table-bordered table-hover">
                                <thead className="table-dark">
                                    <tr>
                                        <th>Phòng ban</th>
                                        <th>Thu nhập</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {data.map((item, index) => (
                                        <tr key={index}>
                                            <td>{item.name}</td>
                                            <td>{item.value.toLocaleString('vi-VN')} VND</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>

                        <div className="col-md-6">
                            <ResponsiveContainer width="100%" height={400}>
                                <PieChart>
                                    <Pie
                                        data={data}
                                        cx="50%"
                                        cy="50%"
                                        outerRadius={130}
                                        dataKey="value"
                                        label
                                        labelLine
                                    >
                                        {data.map((entry, index) => (
                                            <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                        ))}
                                    </Pie>
                                    <Tooltip />
                                    <Legend />
                                </PieChart>
                            </ResponsiveContainer>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default IncomeDepartment;
